window.battlepass_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

const mkBtn=(lbl,w,ht,fill,bord,tc)=>{
  fill=fill||0x1a3a0a;bord=bord||0x3a7a1a;tc=tc||'#90d040';
  const bg=new A();bg.beginFill(fill,1);bg.lineStyle(1,bord);bg.drawRoundedRect(0,0,w,ht,4);bg.endFill();
  const t=new z(lbl,{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:tc,align:'center',wordWrap:true,wordWrapWidth:w-6});
  t.anchor.set(0.5,0.5);t.x=w/2;t.y=ht/2;
  const c=new e();c.addChild(bg,t);c.interactive=true;c.buttonMode=true;
  c.on('mouseover',()=>bg.tint=0xddeecc);c.on('mouseout',()=>bg.tint=0xffffff);
  c._bg=bg;c._txt=t;return c;
};

// ── Наградная ячейка уровня ────────────────────────────────────────
battlepass_elements.lib.Bp_cell=class extends e{
  constructor(){
    super();
    this.bg_mc=new A();this._drawBg('locked');this.addChild(this.bg_mc);
    // Номер уровня
    const lv=new z('',{fontFamily:'Southbank LT',fontSize:10,fill:'#4a6a2a',align:'center'});lv.anchor.set(0.5,0);lv.x=40;lv.y=2;this[lv.name='level_txt']=lv;this.addChild(lv);
    // Иконка награды
    const ic=new z('',{fontFamily:'Arial',fontSize:28,align:'center'});ic.anchor.set(0.5,0.5);ic.x=40;ic.y=44;this[ic.name='icon_txt']=ic;this.addChild(ic);
    // Кол-во / подпись
    const vt=new z('',{fontFamily:'Southbank LT',fontSize:9,fill:'#a0c060',align:'center',wordWrap:true,wordWrapWidth:76});vt.anchor.set(0.5,0);vt.x=40;vt.y=64;this[vt.name='val_txt']=vt;this.addChild(vt);
    // Кнопка забрать
    const cl=mkBtn('ЗАБРАТЬ',70,22,0x1e4a00,0x4a9a10,'#a0e040');cl.x=5;cl.y=78;cl.visible=false;this[cl.name='butt_claim']=cl;this.addChild(cl);
    // Галочка
    const ch=new z('✓',{fontFamily:'Arial',fontSize:22,fill:'#60c020',align:'center'});ch.anchor.set(0.5,0.5);ch.x=40;ch.y=80;ch.visible=false;this[ch.name='check']=ch;this.addChild(ch);
  }
  _drawBg(state){
    this.bg_mc.clear();
    const cols={locked:[0x060c04,0x0e1e0a],current:[0x1a4a00,0x4a9a10],done:[0x0c2008,0x2a5a18],premium:[0x2a1a00,0x8a6010]};
    const c=cols[state]||cols.locked;
    this.bg_mc.beginFill(c[0],state==='current'?1:0.9);
    this.bg_mc.lineStyle(state==='current'?2:1,c[1],state==='current'?1:0.6);
    this.bg_mc.drawRoundedRect(0,0,80,102,4);this.bg_mc.endFill();
  }
  setState(state){
    this._drawBg(state);
    this.butt_claim.visible=(state==='current');
    this.check.visible=(state==='done');
    this.level_txt.style.fill=state==='current'?'#c8e040':state==='done'?'#6a9a3a':'#3a5a2a';
  }
};

// ── Строка уровней (10 ячеек + соединитель) ───────────────────────
battlepass_elements.lib.Bp_row=class extends e{
  constructor(rowIdx){
    super();
    // Соединительная линия
    const line=new A();line.lineStyle(2,0x1e3a10,0.5);line.moveTo(0,51);line.lineTo(880,51);this.addChild(line);
    for(let i=0;i<10;i++){
      const cell=new battlepass_elements.lib.Bp_cell();cell.x=i*90;
      this['cell_'+i]=cell;this.addChild(cell);
    }
  }
};

// ── Полоса прогресса сезона ────────────────────────────────────────
battlepass_elements.lib.Season_bar=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x060e04,1);bg.drawRoundedRect(0,0,900,12,4);bg.endFill();this.addChild(bg);
    this.fill=new A();this.fill.beginFill(0x50a820,1);this.fill.drawRoundedRect(0,0,900,12,4);this.fill.endFill();
    this[this.fill.name='fill']=this.fill;this.addChild(this.fill);
    const lbl=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#6a9a3a'});lbl.x=910;lbl.y=-1;this[lbl.name='lbl_txt']=lbl;this.addChild(lbl);
  }
  setProgress(lv,max){
    this.fill.scale.x=Math.min(1,lv/Math.max(1,max));
    this.lbl_txt.text='Ур. '+lv+' / '+max;
  }
};

// ── Главное окно Бател Пасса ───────────────────────────────────────
battlepass_elements.lib.Battlepass_win=class extends e{
  constructor(){
    super();
    const wb=new A();wb.beginFill(0x060c04,0.97);wb.lineStyle(2,0x284a18,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();this.addChild(wb);
    const hb=new A();hb.beginFill(0x081802,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x284a18,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);this.addChild(hb,hl);
    const ttl=new z('БАТЕЛ ПАСС',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#b8d840',letterSpacing:4,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});ttl.x=20;ttl.y=12;this.addChild(ttl);
    // Сезон / XP инфо
    const si=new z('Сезон 1 · Зона',{fontFamily:'Southbank LT',fontSize:12,fill:'#5a7a3a'});si.x=240;si.y=16;this.addChild(si);
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;cl.interactive=true;cl.buttonMode=true;cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // Полоса прогресса
    const sb=new battlepass_elements.lib.Season_bar();sb.x=20;sb.y=52;this[sb.name='season_bar']=sb;this.addChild(sb);
    const xpt=new z('',{fontFamily:'Southbank LT',fontSize:10,fill:'#4a6a2a'});xpt.x=20;xpt.y=68;this[xpt.name='xp_txt']=xpt;this.addChild(xpt);
    // 5 строк по 10 ячеек (50 уровней на экране, прокрутка через кнопки)
    const rows=new e();rows.x=18;rows.y=80;
    for(let r=0;r<5;r++){
      const row=new battlepass_elements.lib.Bp_row(r);row.y=r*100;rows['row_'+r]=row;rows.addChild(row);
    }
    this[rows.name='bp_rows']=rows;this.addChild(rows);
    // Кнопки листания
    const prev=mkBtn('◀ НАЗАД',100,30,0x0e2208,0x3a6018,'#70b030');prev.x=20;prev.y=492;this[prev.name='butt_prev']=prev;this.addChild(prev);
    const next=mkBtn('ВПЕРЁД ▶',100,30,0x0e2208,0x3a6018,'#70b030');next.x=1076;next.y=492;this[next.name='butt_next']=next;this.addChild(next);
    const paget=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#5a7a3a',align:'center'});paget.anchor.set(0.5,0.5);paget.x=600;paget.y=507;this[paget.name='page_txt']=paget;this.addChild(paget);
    // Кнопка «Забрать все»
    const ca=mkBtn('ЗАБРАТЬ ВСЕ',160,30,0x1e4a00,0x4a9a10,'#a0e040');ca.x=510;ca.y=492;this[ca.name='butt_claim_all']=ca;this.addChild(ca);
  }
};

battlepass_elements.lib.battlepass_elements=class extends n{
  constructor(){super({duration:1,framerate:30});const b=new battlepass_elements.lib.Battlepass_win();this[b.name='battlepass_win']=b;this.addChild(b);}
};
battlepass_elements.stage=battlepass_elements.lib.battlepass_elements}};
